insert into public.knowledge_base (intent, category, title, approved_answer, keywords, allowed_variation, requires_approval, priority, active) values
('service_info','guide_v1','الخدمات','نقدم خدمات تنظيم وترتيب المساحات السكنية والتجارية، وتشمل غرف الملابس والخزائن، المطابخ، غرف النوم والأطفال، غرف الألعاب، المستودعات، المكاتب، بالإضافة إلى ترتيب المنزل بعد الانتقال.', array['خدمات','وش تسوون','ايش تقدمون','خدماتكم','تنظيم','ترتيب'], true, false, 90, true),
('service_info','guide_v1','طريقة العمل','نبدأ بفرز وتصنيف الأغراض، والتخلص من الفوضى والتكدس، ثم نعيد توزيعها وتنظيمها بطريقة عملية، ونستغل المساحة بأفضل شكل، وننشئ نظام واضح يسهل المحافظة عليه مستقبلاً.', array['كيف تشتغلون','طريقة العمل','كيف تسوون','آلية العمل'], true, false, 85, true),
('service_info','guide_v1','بالمشروع لا بالساعة','خدمتنا تكون بالمشروع، وليست بالساعة أو بعدد العاملات. نحدد الفريق والوقت المناسب حسب حجم العمل.', array['بالساعة','عدد العاملات','كيف تحسبون','بالمشروع'], true, false, 70, true),
('service_info','guide_v1','ما تشمله الخدمة','تشمل الخدمة فرز وتصنيف الأغراض، التخلص من الفوضى والتكدس، ترتيب وتنظيم المساحة، استغلالها بشكل عملي، وإنشاء نظام يسهل المحافظة عليه.', array['وش يشمل','تشمل ايش','الخدمة تشمل'], true, false, 70, true),
('ask_organizers','guide_v1','المنظمات منفصلة','المنظمات والأدوات تُحسب بشكل منفصل حسب الاحتياج، لأن كل مساحة تختلف عن الثانية. نحدد الخيارات والكميات المناسبة، وما يتم اعتماد أو شراء شيء إلا بعد موافقتك.', array['منظمات','ادوات','علاقات','علب','سلال','منفصلة'], true, false, 75, true),
('ask_organizers','guide_v1','ليش المنظمات منفصلة','لأن الاحتياج يختلف بشكل كبير من عميل لآخر؛ غرفة ممكن تحتاج 50 علاقة وأخرى 100 أو 200، بالإضافة للسلال والمقسمات وغيرها. لذلك نحاسب فقط على القطع المستخدمة فعليًا.', array['ليش منفصلة','ليش المنظمات','ليه لحال'], true, false, 65, true),
('ask_organizers','guide_v1','توفير المنظمات','نقدر نوفر المنظمات والعلاقات وحلول التخزين المناسبة، ونشاركك الخيارات قبل اعتمادها، وما نشتري شيء إلا بعد موافقتك.', array['اشتري المنظمات','توفرون منظمات','تجيبون المنظمات'], true, false, 65, true),
('ask_cleaning','guide_v1','تنظيف خفيف','نقدم تنظيف خفيف مرتبط بعملية التنظيم، مثل مسح الأدراج والأرفف والخزائن وإزالة الغبار البسيط. أما التنظيف العميق للغرفة أو المنزل فمو ضمن الخدمة.', array['تنظيف','تنظفون','نظافة','غبار'], true, false, 65, true),
('service_info','guide_v1','لا يوجد كوي','ما نقدم خدمة الكوي حاليًا، لكن نقدر نفرز ونصنف ونعلق ونرتب الملابس داخل الخزائن بالكامل.', array['كوي','مكواة','تكوون','كوي ملابس'], true, false, 60, true),
('ask_moving','guide_v1','الترتيب بعد النقل','نعم، نقدم خدمة الترتيب بعد النقل، وتشمل تفريغ الملابس والأغراض من الكراتين، وفرزها وتصنيفها، ثم ترتيبها وتنظيمها داخل الخزائن والمساحات الجديدة.', array['بعد النقل','انتقلنا','بيت جديد','ترتيب بعد الانتقال'], true, false, 65, true),
('ask_moving','guide_v1','لا نقدم النقل','لا، ما نقدم خدمة نقل الأغراض، لكن نقدم خدمة التفريغ والترتيب والتنظيم بعد وصول الأغراض للموقع الجديد.', array['نقل عفش','تنقلون','ترحيل','دباب'], true, false, 60, true),
('service_info','guide_v1','كيف نرتب الملابس','نفرغ ونفرز الملابس حسب الفئات والاستخدام، ثم نعيد توزيعها داخل الخزائن والأدراج بطريقة عملية، ونستغل المساحات بحلول تنظيم مناسبة، وننشئ نظام يسهل المحافظة عليه.', array['ترتيب الملابس','غرفة الملابس','دولاب','خزانة'], true, false, 65, true),
('service_info','guide_v1','كيف نرتب المطبخ','نفرز ونصنف محتويات المطبخ حسب الاستخدام، ثم نعيد توزيعها على الخزائن والأدراج بطريقة تسهّل الوصول لها، ونستغل المساحات بحلول تنظيم مناسبة، وننشئ نظام عملي للاستخدام اليومي.', array['ترتيب المطبخ','المطبخ','مطبخ'], true, false, 65, true),
('service_info','guide_v1','كيف نرتب المستودع','نفرغ ونفرز الأغراض حسب الفئات، ونحدد مكان لكل فئة حسب أولوية الاستخدام، ثم نستغل الرفوف والمساحات بشكل أفضل ونستخدم الصناديق والمنظمات والليبلز عند الحاجة، بحيث يصير المخزن واضح وسهل المحافظة عليه.', array['مستودع','مخزن','ستور','رفوف'], true, false, 60, true),
('send_media','guide_v1','الفوضى عادية','أبد عادي، وهذا أساس شغلنا. أغلب المساحات اللي نستلمها تحتاج إعادة تنظيم، فلا تشيل هم وأرسل الصور مثل ما هي.', array['حوسة','فوضى','مكرمشة','مب مرتبة','أستحي'], true, false, 60, true),
('ask_duration','guide_v1','مدة التنفيذ','المدة تعتمد على حجم المشروع وكمية الأغراض. أغلب المشاريع تُحدد مدتها بعد مراجعة الصور، والمشاريع الكبيرة ممكن تحتاج عدة أيام عمل.', array['كم يستغرق','كم مدة','كم ياخذ','كم يوم','الوقت'], true, false, 65, true),
('service_area','guide_v1','داخل الرياض فقط','حاليًا خدماتنا متوفرة داخل مدينة الرياض فقط.', array['خارج الرياض','جدة','الدمام','مدينتي','تخدمون','وين'], true, false, 70, true),
('service_info','guide_v1','فريق العمل','فريق العمل يتكون من منظمات مدربات، مع إشراف على تنفيذ المشروع لضمان جودة وترتيب موحد.', array['الفريق','مين يجي','العاملات','منظمات','مشرفة'], true, false, 60, true),
('service_info','guide_v1','تجهيزات العروس','نعم، نقدر نفرز ونصنف وننظم الملابس والإكسسوارات وترتيبها داخل غرفة الملابس والخزائن. خدمة الكوي غير متوفرة.', array['عروس','تجهيز العروس','جهاز العروس','دفة'], true, false, 60, true),
('service_info','guide_v1','هدف الخدمة','هدفنا مو ترتيب مؤقت فقط؛ نعمل على التخلص من الفوضى، رفع جودة استخدام المكان، واستغلال المساحة بشكل أفضل، وإنشاء نظام يسهل المحافظة عليه يوميًا.', array['الهدف','ليش','الفايدة','وش الفرق'], true, false, 55, true),
('service_info','guide_v1','زيارة المتابعة','خدمتنا تركّز على تنفيذ الترتيب والتنظيم بأفضل شكل، ولا تشمل زيارات متابعة مجانية بعد التنفيذ.', array['متابعة','زيارة متابعة','ترجعون','بعد التنفيذ','تتابعون'], true, false, 55, true),
('service_info','guide_v1','لا يوجد تدريب','خدمتنا هي تنظيم وترتيب المساحات، ولا نقدم تدريبًا للعاملات المنزليات.', array['تدريب','تدربون','العاملة','الشغالة','تعليم'], true, false, 55, true);
